ALTER TABLE public.group_buying_campaigns ADD COLUMN lifecycle text NOT NULL DEFAULT 'draft' CHECK(lifecycle IN ('draft','active','target_reached','completed','expired','cancelled')), ADD COLUMN normal_price numeric(12,2) NOT NULL DEFAULT 0 CHECK(normal_price>=0), ADD COLUMN max_quantity integer NOT NULL DEFAULT 1 CHECK(max_quantity>0), ADD COLUMN starts_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN committed_quantity integer NOT NULL DEFAULT 0 CHECK(committed_quantity>=0), ADD COLUMN business_count integer NOT NULL DEFAULT 0 CHECK(business_count>=0);
UPDATE public.group_buying_campaigns c SET lifecycle=CASE WHEN c.status='open' AND c.closes_at>now() THEN 'active' WHEN c.status='open' THEN 'expired' ELSE 'draft' END,normal_price=p.price,max_quantity=GREATEST(c.target_quantity,p.stock) FROM public.products p WHERE p.id=c.product_id;
COMMENT ON COLUMN public.group_buying_campaigns.status IS 'DEPRECATED: use lifecycle; old status retained for compatibility';
ALTER TABLE public.group_buying_participants ADD COLUMN delivery jsonb NOT NULL DEFAULT '{}', ADD COLUMN order_id uuid REFERENCES public.orders(id), ADD COLUMN commitment_status text NOT NULL DEFAULT 'committed' CHECK(commitment_status IN ('committed','ordered','released'));
ALTER TABLE public.orders ADD COLUMN campaign_id uuid REFERENCES public.group_buying_campaigns(id);
CREATE UNIQUE INDEX campaign_buyer_order ON public.orders(campaign_id,buyer_id) WHERE campaign_id IS NOT NULL;
REVOKE INSERT,UPDATE,DELETE ON public.group_buying_campaigns FROM authenticated; REVOKE INSERT,UPDATE,DELETE ON public.group_buying_participants FROM authenticated;
CREATE POLICY campaign_public_lifecycle ON public.group_buying_campaigns FOR SELECT USING(lifecycle IN ('active','target_reached','completed','expired','cancelled') AND public.public_product(product_id));
CREATE POLICY campaign_participant_read ON public.group_buying_campaigns FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.group_buying_participants g WHERE g.campaign_id=group_buying_campaigns.id AND g.user_id=auth.uid()));
CREATE FUNCTION public.group_buyer_eligible() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'buyer') AND EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.group_buyer_eligible() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.group_buyer_eligible() TO authenticated;